import assert from 'node:assert/strict';
import {parseGcodeMetadata} from './3d-artprint-gcode-estimator.js';

const orca = [
 '; generated by OrcaSlicer',
 '; filament used [g] = 23.48',
 '; estimated printing time (normal mode) = 2h 13m 30s',
 '; filament_type = PETG',
 '; layer_height = 0.2',
 'G1 X10 Y10 E0.8'
].join('\n');
let r=parseGcodeMetadata(orca);
assert.equal(r.grams,23.48);
assert.ok(Math.abs(r.hours-(2+13/60+30/3600))<1e-8);
assert.equal(r.material,'PETG');
assert.equal(r.layerHeight,0.2);
const withoutAnnotations = parseGcodeMetadata('G28\nG1 X10 Y20 E1.2\nG1 X40 E8.4');
assert.equal(withoutAnnotations.grams,null);
assert.equal(withoutAnnotations.hours,null);
const bad = parseGcodeMetadata('; filament used [g] = -45\n; printing time = nonsense');
assert.equal(bad.grams,null);
assert.equal(bad.hours,null);
const packedOrcaGcode = parseGcodeMetadata([
'; estimated printing time (normal mode) = 0d 0h 44m 1s',
';right_extruder_material:PETG',
'; filament used [g] = 26.50, 0.00, 0.00, 0.00',
'; total filament used [g] = 26.50',
'; total layers count = 160'
].join('\n'));
assert.equal(packedOrcaGcode.grams,26.5);
assert.ok(Math.abs(packedOrcaGcode.hours-(44*60+1)/3600)<1e-8);
assert.equal(packedOrcaGcode.material,'PETG');
console.log('G-code metadata parser: 4 fixtures passed.');
